#!/usr/bin/env bash
# The QA gate: the checked-in push-target list must match `src/` before the
# suite runs, then the suite runs through the shared build lock.
#
#   ./qa/run-tests.sh            # scan freshness + ./scripts/check.sh test-only
#   ./qa/run-tests.sh check      # scan freshness + ./scripts/check.sh (types + build + tests)
#
# Why the gate: `qa/push-targets.ts` is generated by `bun qa/scan-push-targets.mjs`
# because the test sandbox cannot read the filesystem. A stale snapshot is how a
# `nav.push("typo")` ships green — the scan in `qa/registry.test.ts` would still
# be checking yesterday's names. This script refuses to run a stale one.
#
# Never call `nsh test` directly in this repo (the build cache is shared by the
# parallel agents); `scripts/check.sh` takes the lock and waits.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

bun qa/scan-push-targets.mjs --check

# `check.sh check` is types-only; this gate always ends with the suite.
case "${1:-test-only}" in
  check) exec ./scripts/check.sh test ;;
  *)     exec ./scripts/check.sh "${1:-test-only}" ;;
esac
